// Text as the terminal draws it: the control characters a drawing may not
// hold, how many cells a string takes (a CJK character or an emoji two, a
// combining mark none) and cutting to a width. No `$`, no I/O: the hooks module
// and the graph client both import it.

/**
 * C0 and C1 controls and DEL, tab and newline included, and the Unicode line
 * and paragraph separators: the engine refuses a tree that holds most of
 * them, a newline breaks a row, and YAML 1.1 (PyYAML) reads U+2028 and U+2029
 * as line breaks too.
 */
const CONTROL = /[\u0000-\u001f\u007f-\u009f\u2028\u2029]+/g

/** The same, but for tab and newline: what a block of source lines may keep. */
const CONTROL_IN_LINES = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f\u2028\u2029]+/g

/** Whether `text` holds a character `clean` would change. */
export const hasControl = (text: string): boolean => /[\u0000-\u001f\u007f-\u009f\u2028\u2029]/.test(text)

/** `text` with each run of control characters as one space: what a one-line label may hold. */
export function clean(text: string): string {
  return text.replace(CONTROL, ' ')
}

/** `text` with its line breaks made `\n` and every other control character but tab a space. */
export function cleanLines(text: string): string {
  return text.replace(/\r\n?/g, '\n').replace(CONTROL_IN_LINES, ' ')
}

// East Asian Wide and Fullwidth, and the emoji drawn two cells wide: the common
// ranges, not the whole Unicode table.
const WIDE: readonly (readonly [number, number])[] = [
  [0x1100, 0x115f],
  [0x231a, 0x231b],
  [0x2329, 0x232a],
  [0x23e9, 0x23ec],
  [0x23f0, 0x23f3],
  [0x25fd, 0x25fe],
  [0x2614, 0x2615],
  [0x2648, 0x2653],
  [0x267f, 0x267f],
  [0x2693, 0x2693],
  [0x26a1, 0x26a1],
  [0x26aa, 0x26ab],
  [0x26bd, 0x26be],
  [0x26c4, 0x26c5],
  [0x26ce, 0x26ce],
  [0x26d4, 0x26d4],
  [0x26ea, 0x26ea],
  [0x26f2, 0x26f5],
  [0x26fa, 0x26fd],
  [0x2705, 0x2705],
  [0x270a, 0x270b],
  [0x2728, 0x2728],
  [0x274c, 0x274e],
  [0x2753, 0x2757],
  [0x2795, 0x2797],
  [0x27b0, 0x27bf],
  [0x2b1b, 0x2b1c],
  [0x2b50, 0x2b55],
  [0x2e80, 0x303e],
  [0x3041, 0x33ff],
  [0x3400, 0x4dbf],
  [0x4e00, 0x9fff],
  [0xa000, 0xa4cf],
  [0xa960, 0xa97f],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe10, 0xfe19],
  [0xfe30, 0xfe6f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
  [0x16fe0, 0x16fe4],
  [0x17000, 0x18cff],
  [0x1b000, 0x1b2ff],
  [0x1f004, 0x1f004],
  [0x1f0cf, 0x1f0cf],
  [0x1f18e, 0x1f18e],
  [0x1f191, 0x1f19a],
  [0x1f200, 0x1f251],
  [0x1f300, 0x1f64f],
  [0x1f680, 0x1f6ff],
  [0x1f7e0, 0x1f7eb],
  [0x1f90c, 0x1f9ff],
  [0x1fa70, 0x1faff],
  [0x20000, 0x3fffd],
]

const isZeroWidth = (cp: number): boolean =>
  (cp >= 0x300 && cp <= 0x36f) ||
  (cp >= 0x1ab0 && cp <= 0x1aff) ||
  (cp >= 0x1dc0 && cp <= 0x1dff) ||
  (cp >= 0x200b && cp <= 0x200f) ||
  (cp >= 0x20d0 && cp <= 0x20ff) ||
  (cp >= 0xfe00 && cp <= 0xfe0f) ||
  (cp >= 0xe0100 && cp <= 0xe01ef)

/** The cells one code point takes: 0, 1 or 2. */
export function charWidth(cp: number): number {
  if (cp < 0x300) {
    return 1
  }
  if (isZeroWidth(cp)) {
    return 0
  }

  return WIDE.some(([lo, hi]) => cp >= lo && cp <= hi) ? 2 : 1
}

const widthOfChar = (ch: string): number => charWidth(ch.codePointAt(0) ?? 0)

/** The cells `text` takes on one row. */
export function widthOf(text: string): number {
  // Printable ASCII, the usual case, is one cell a character.
  if (/^[\x20-\x7e]*$/.test(text)) {
    return text.length
  }

  let width = 0
  for (const ch of text) {
    width += widthOfChar(ch)
  }

  return width
}

/** `text` cut to `width` cells, an ellipsis last when it was cut. */
export function cut(text: string, width: number): string {
  if (width <= 0) {
    return ''
  }
  if (widthOf(text) <= width) {
    return text
  }

  let kept = ''
  let used = 0
  for (const ch of text) {
    const w = widthOfChar(ch)
    if (used + w > width - 1) {
      break
    }
    kept += ch
    used += w
  }

  return `${kept}…`
}

/** `text` cut from the start to `width` cells, keeping its end: `…c › Offline editing`. */
export function cutStart(text: string, width: number): string {
  if (width <= 0) {
    return ''
  }
  if (widthOf(text) <= width) {
    return text
  }

  const chars = [...text]
  let kept = ''
  let used = 0
  for (let i = chars.length - 1; i >= 0; i--) {
    const ch = chars[i] ?? ''
    const w = widthOfChar(ch)
    if (used + w > width - 1) {
      break
    }
    kept = ch + kept
    used += w
  }

  return `…${kept}`
}

/** `text` padded with spaces to `width` cells. */
export function padCells(text: string, width: number): string {
  const length = widthOf(text)

  return length >= width ? text : text + ' '.repeat(width - length)
}

files.hooks/views.ts:
// The pane's and the band's trees: header, tabs, breadcrumb, the Miller-column
// browser, the op feed, the review queue and a text graph for the surfaces
// with no Client. Built from the element table `$.ui.resolve(e)` handed out and
// a model of plain data and callbacks; no `$` here (register.ts binds it).
import type { Elements, OmniInfo, OmniOp, RenderElement, RenderSurface } from 'claude-code'

import type { EgoProps } from './canvas'
import {
  byName,
  conflictsOf,
  deltaOf,
  feedRow,
  fit,
  fitStart,
  humanType,
  msOf,
  nameOf,
  padEnd,
  plural,
  queueOf,
  totalsLine,
} from './graphstore'
import type { Adapter, Graph, Totals } from './graphstore'
import { clean, cleanLines, widthOf } from './text'

export type Tab = 'graph' | 'browse' | 'feed' | 'queue'

export const TABS: readonly { tab: Tab; label: string; hotkey: string }[] = [
  { tab: 'graph', label: 'Graph', hotkey: '1' },
  { tab: 'browse', label: 'Browse', hotkey: '2' },
  { tab: 'feed', label: 'Feed', hotkey: '3' },
  { tab: 'queue', label: 'Queue', hotkey: '4' },
]

type Table = Elements[RenderSurface]

/** What a press asks for; register.ts binds each to `$`. */
export type Actions = {
  tab: (tab: Tab) => void
  follow: () => void
  /** A new browse path, its last node the selection. */
  pick: (trail: string[]) => void
  label: (label: string) => void
  back: () => void
  page: (page: number) => void
  exportPatch: (id: string) => void
}

export type PaneModel = {
  surface: RenderSurface
  columns: number
  rows: number
  info: OmniInfo | null
  totals: Totals
  feed: readonly OmniOp[]
  tab: Tab
  trail: readonly string[]
  isFollowing: boolean
  browseLabel: string | null
  queuePage: number
  notice: string | null
  graph: Graph
  a: Adapter
  /** The graph client, built where its module path is read (register.ts); null where the surface has none. */
  graphClient: RenderElement | null
  ego: EgoProps
  /** The rows the graph region takes. */
  graphRows: number
  /** The selection's source lines, when its node names a readable path:line. */
  source: { path: string; line: number; text: string } | null
  act: Actions
}

const clamp = (n: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, n))

/** How the Graph tab splits its rows: the graph, the Miller columns, the feed strip. */
export function graphTabRows(rows: number, feedLength: number): { graph: number; miller: number; feed: number } {
  const feed = clamp(feedLength, 1, 4)
  const left = Math.max(6, rows - 3 - feed - 1)
  const miller = left >= 22 ? clamp(Math.floor(left * 0.38), 7, 12) : 0
  const graph = clamp(left - miller - (miller > 0 ? 1 : 0), 6, 30)

  return { graph, miller, feed }
}

// ------------------------------------------------------------------ the pane

export function paneOf(el: Table, m: PaneModel): RenderElement {
  const { Box } = el
  const body: RenderElement[] = [headerOf(el, m), tabsOf(el, m), crumbOf(el, m)]

  if (m.info?.problem) {
    body.push(el.Text({ color: 'warning', wrap: 'truncate-end', children: [fit(m.info.problem, m.columns)] }))
  }

  if (m.tab === 'graph') {
    const split = graphTabRows(m.rows, m.feed.length)
    body.push(graphOf(el, m))
    if (split.miller > 0) {
      body.push(ruleOf(el, m.columns, 'browse'))
      body.push(millerOf(el, m, split.miller))
    }
    body.push(ruleOf(el, m.columns, 'feed'))
    body.push(...feedRowsOf(el, m, split.feed, false))
  } else if (m.tab === 'browse') {
    const detail = detailOf(el, m)
    body.push(browseBarOf(el, m))
    body.push(millerOf(el, m, clamp(m.rows - 4 - detail.rows, 6, 40)))
    body.push(...detail.elements)
  } else if (m.tab === 'feed') {
    body.push(...feedRowsOf(el, m, Math.max(3, m.rows - 3), true))
  } else {
    body.push(...queueTabOf(el, m))
  }

  return Box({ flexDirection: 'column', children: body })
}

function headerOf(el: Table, m: PaneModel): RenderElement {
  const { Box, Text } = el
  const where = [m.info?.name ?? 'no store', m.info?.branch].filter((part): part is string => !!part).join(' · ')
  const right = totalsLine(m.totals)
  const leftWidth = Math.max(10, m.columns - widthOf(right) - 2)

  return Box({
    flexDirection: 'row',
    justifyContent: 'space-between',
    children: [
      Text({
        wrap: 'truncate-end',
        children: [Text({ color: 'claude', children: ['◉ '] }), Text({ bold: true, children: ['omnigraph'] }), fit(` · ${where}`, leftWidth - 11)],
      }),
      Text({
        children: [
          `${plural(m.totals.ops, 'op')} · ${deltaOf(m.totals.dNodes, 'n')} ${deltaOf(m.totals.dEdges, 'e')} · `,
          Text({ ...(m.totals.errors > 0 ? { color: 'error' } : { dimColor: true }), children: [`${m.totals.errors} ×`] }),
        ],
      }),
    ],
  })
}

function tabsOf(el: Table, m: PaneModel): RenderElement {
  const { Box, Button, Text } = el
  const hint =
    m.tab === 'graph'
      ? 'click the graph to browse with ↑↓←→'
      : m.tab === 'browse'
        ? 'Enter opens · h goes back'
        : m.tab === 'feed'
          ? `${plural(m.feed.length, 'op')} kept`
          : 'export writes a patch; nothing is applied'

  return Box({
    flexDirection: 'row',
    columnGap: 2,
    children: [
      ...TABS.map(({ tab, label, hotkey }) =>
        Button({ key: `tab-${tab}`, label, hotkey, plain: true, dimColor: m.tab !== tab, onPress: () => m.act.tab(tab) }),
      ),
      Button({
        key: 'follow',
        label: m.isFollowing ? 'following ops' : 'follow ops',
        hotkey: 'f',
        plain: true,
        dimColor: !m.isFollowing,
        onPress: () => m.act.follow(),
      }),
      Text({ dimColor: true, wrap: 'truncate-end', children: [hint] }),
    ],
  })
}

/** The browse path as one line: `Offline editing & sync › contains › Conflict toast hides unsynced edits`. */
export function crumbText(graph: Graph, trail: readonly string[]): string {
  const parts: string[] = []

  trail.forEach((id, i) => {
    const before = trail[i - 1]
    if (before !== undefined) {
      parts.push(relationWord(graph, before, id))
    }
    parts.push(nameOf(graph, id))
  })

  return parts.join(' › ')
}

function relationWord(graph: Graph, from: string, to: string): string {
  const out = (graph.out.get(from) ?? []).find(edge => edge.to === to)

  if (out) {
    return humanType(out.type)
  }

  const back = (graph.into.get(from) ?? []).find(edge => edge.from === to)

  return back ? `← ${humanType(back.type)}` : '·'
}

function crumbOf(el: Table, m: PaneModel): RenderElement {
  const { Text } = el
  const mark = m.isFollowing ? ' ● live' : ' ○ browsing'
  const text = m.trail.length > 0 ? crumbText(m.graph, m.trail) : m.info?.isPresent ? 'nothing selected yet' : 'waiting for a store'

  return Text({
    wrap: 'truncate-end',
    children: [
      fitStart(text, Math.max(8, m.columns - widthOf(mark))),
      Text({ ...(m.isFollowing ? { color: 'success' } : { dimColor: true }), children: [mark] }),
    ],
  })
}

function ruleOf(el: Table, columns: number, title: string): RenderElement {
  return el.Text({ dimColor: true, wrap: 'truncate-end', children: [`── ${title} ${'─'.repeat(Math.max(0, columns - title.length - 4))}`] })
}

// ----------------------------------------------------------------- the graph

function graphOf(el: Table, m: PaneModel): RenderElement {
  if (m.graphClient !== null) {
    return m.graphClient
  }

  return el.Box({ flexDirection: 'column', children: graphTextOf(m.ego, m.columns, m.graphRows).map(line => el.Text({ wrap: 'truncate-end', children: [line] })) })
}

/** The graph as lines of text, for a surface with no Client: the centre, then a line per group. */
export function graphTextOf(ego: EgoProps, columns: number, rows: number): string[] {
  if (ego.empty !== null) {
    return [fit(ego.empty, columns)]
  }

  const center = ego.nodes.find(node => node.side === 'center')
  const lines = [fit(`◉ ${center?.name ?? ego.center}`, columns)]

  ego.groups.forEach((group, index) => {
    const members = ego.nodes.filter(node => node.group === index)
    const names = members.map(node => (node.more > 0 ? `+${node.more} more` : `${node.isSelected ? '▶ ' : ''}${node.name}`))
    lines.push(fit(`  ${group.dir === 'in' ? '←' : '→'} ${group.title.replace(/^← /, '')}: ${names.join(', ')}`, columns))
  })

  return lines.slice(0, Math.max(1, rows))
}

// ------------------------------------------------------------ the browser

type Line =
  | { kind: 'head'; text: string }
  | { kind: 'item'; key: string; id: string; name: string; isOnTrail: boolean; onPress: () => void }

type Column = { title: string; lines: Line[] }

/** The browser's columns: one label's nodes, then each trail node's relations. */
export function columnsOf(m: Pick<PaneModel, 'graph' | 'trail' | 'browseLabel' | 'act'>): Column[] {
  const { graph, trail } = m
  const first = trail[0]
  const label = m.browseLabel ?? (first !== undefined ? graph.nodes.get(first)?.label : undefined) ?? graph.labels[0]

  if (label === undefined) {
    return []
  }

  const ids = graph.byLabel.get(label) ?? []
  const columns: Column[] = [
    {
      title: `${label} ${ids.length}`,
      lines: ids.map(id => ({
        kind: 'item',
        key: `m0:${id}`,
        id,
        name: nameOf(graph, id),
        isOnTrail: id === first,
        onPress: () => m.act.pick([id]),
      })),
    },
  ]

  // A first column of another label than the trail's starts a new trail.
  const isOwnTrail = first !== undefined && graph.nodes.get(first)?.label === label

  if (!isOwnTrail) {
    return columns
  }

  trail.forEach((id, k) => {
    const next = trail[k + 1]
    const groups = new Map<string, { head: string; ids: Set<string> }>()

    for (const edge of graph.out.get(id) ?? []) {
      const key = `→\u0000${edge.type}\u0000${graph.nodes.get(edge.to)?.label ?? '?'}`
      addLine(groups, key, `→ ${humanType(edge.type)} · ${graph.nodes.get(edge.to)?.label ?? '?'}`, edge.to)
    }
    for (const edge of graph.into.get(id) ?? []) {
      const key = `←\u0000${edge.type}\u0000${graph.nodes.get(edge.from)?.label ?? '?'}`
      addLine(groups, key, `← ${humanType(edge.type)} · ${graph.nodes.get(edge.from)?.label ?? '?'}`, edge.from)
    }

    const lines: Line[] = []
    let g = 0
    for (const group of groups.values()) {
      lines.push({ kind: 'head', text: `${group.head} ${group.ids.size}` })
      for (const target of byName(graph, group.ids)) {
        lines.push({
          kind: 'item',
          key: `m${k + 1}:${g}:${target}`,
          id: target,
          name: nameOf(graph, target),
          isOnTrail: target === next,
          onPress: () => m.act.pick([...trail.slice(0, k + 1), target]),
        })
      }
      g++
    }
    if (lines.length === 0) {
      lines.push({ kind: 'head', text: 'no relations' })
    }
    columns.push({ title: nameOf(graph, id), lines })
  })

  return columns
}

/** Adds `id` to its group once: a Set, as a hub's group can hold thousands. */
function addLine(groups: Map<string, { head: string; ids: Set<string> }>, key: string, head: string, id: string): void {
  const group = groups.get(key)

  if (group) {
    group.ids.add(id)
  } else {
    groups.set(key, { head, ids: new Set([id]) })
  }
}

/** The lines of a column that fit in `rows`, kept around the trail's line, with `↑ n more` / `↓ n more`. */
export function windowOf(lines: readonly Line[], rows: number): { lines: Line[]; above: number; below: number } {
  if (lines.length <= rows) {
    return { lines: [...lines], above: 0, below: 0 }
  }

  const room = Math.max(1, rows - 2)
  const on = lines.findIndex(line => line.kind === 'item' && line.isOnTrail)
  const start = clamp((on < 0 ? 0 : on) - Math.floor(room / 2), 0, lines.length - room)

  return { lines: lines.slice(start, start + room), above: start, below: lines.length - start - room }
}

function millerOf(el: Table, m: PaneModel, rows: number): RenderElement {
  const { Box, Button, Text } = el
  const all = columnsOf(m)

  if (all.length === 0) {
    return Text({ dimColor: true, children: [m.info?.isPresent ? 'the store has no nodes' : 'no store to browse'] })
  }

  const count = clamp(Math.floor((m.columns + 1) / 24), 1, 4)
  const shown = all.slice(-count)
  const width = Math.max(10, Math.floor((m.columns - (shown.length - 1)) / shown.length))
  const itemRows = Math.max(1, rows - 1)

  return Box({
    flexDirection: 'row',
    columnGap: 1,
    children: shown.map((column, c) => {
      const view = windowOf(column.lines, itemRows)
      const children: RenderElement[] = [Text({ bold: true, wrap: 'truncate-end', children: [fit(column.title, width)] })]

      if (view.above > 0) {
        children.push(Text({ dimColor: true, children: [`↑ ${view.above} more`] }))
      }
      for (const line of view.lines) {
        if (line.kind === 'head') {
          children.push(Text({ dimColor: true, wrap: 'truncate-end', children: [fit(line.text, width)] }))
        } else {
          children.push(
            Button({
              key: line.key,
              label: fit(`${line.isOnTrail ? '▶ ' : '  '}${line.name}`, width),
              plain: true,
              dimColor: !line.isOnTrail && c < shown.length - 1,
              onPress: line.onPress,
            }),
          )
        }
      }
      if (view.below > 0) {
        children.push(Text({ dimColor: true, children: [`↓ ${view.below} more`] }))
      }

      return Box({ key: `col-${c}`, flexDirection: 'column', width, children })
    }),
  })
}

function browseBarOf(el: Table, m: PaneModel): RenderElement {
  const { Box, Button, Text } = el
  const first = m.trail[0]
  const current = m.browseLabel ?? (first !== undefined ? m.graph.nodes.get(first)?.label : undefined) ?? m.graph.labels[0] ?? ''
  const children: RenderElement[] = []

  // Mobile has no Select (its table completes one to an empty fragment): the
  // surface decides, and the cast only types the table for it.
  if (m.surface !== 'mobile' && m.graph.labels.length > 0) {
    children.push(
      (el as Elements['terminal']).Select({
        key: 'label',
        label: 'type',
        value: current,
        options: m.graph.labels.map(label => ({ value: label, label: `${label} ${m.graph.byLabel.get(label)?.length ?? 0}` })),
        onSelect: value => m.act.label(value),
      }),
    )
  } else {
    children.push(Text({ dimColor: true, children: [`type ${current}`] }))
  }
  children.push(Button({ key: 'back', label: 'back', hotkey: 'h', plain: true, dimColor: true, onPress: () => m.act.back() }))

  return Box({ flexDirection: 'row', columnGap: 2, children })
}

function detailOf(el: Table, m: PaneModel): { elements: RenderElement[]; rows: number } {
  const { Text } = el
  const id = m.trail[m.trail.length - 1]
  const node = id === undefined ? undefined : m.graph.nodes.get(id)

  if (id === undefined || node === undefined) {
    return { elements: [], rows: 0 }
  }

  const skip = new Set([...m.a.nameKeys, m.a.statusKey, m.a.sourceKey])
  const props = Object.entries(node.props)
    .filter(([key]) => !skip.has(key))
    .slice(0, 6)
    .map(([key, value]) => fit(clean(`${key}: ${typeof value === 'string' ? value : JSON.stringify(value)}`), m.columns))
  const elements: RenderElement[] = [
    ruleOf(el, m.columns, 'detail'),
    Text({ bold: true, wrap: 'truncate-end', children: [fit(node.name, m.columns)] }),
    Text({ dimColor: true, wrap: 'truncate-end', children: [fit(clean(`${node.id} · ${node.label}${node.status ? ` · ${node.status}` : ''}`), m.columns)] }),
    ...props.map(line => Text({ wrap: 'truncate-end', children: [line] })),
  ]
  let rows = 3 + props.length

  if (m.source !== null) {
    elements.push(Text({ dimColor: true, wrap: 'truncate-end', children: [fit(clean(`${m.source.path}:${m.source.line}`), m.columns)] }))
    elements.push(el.Code({ source: cleanLines(m.source.text), path: m.source.path, startLine: Math.max(1, m.source.line - 2), wrap: 'truncate-end' }))
    rows += 1 + m.source.text.split('\n').length
  }

  return { elements, rows }
}

// ------------------------------------------------------------------ the feed

function feedRowsOf(el: Table, m: PaneModel, rows: number, isFull: boolean): RenderElement[] {
  const { Text } = el

  if (m.feed.length === 0) {
    return [Text({ dimColor: true, wrap: 'truncate-end', children: [fit('no ops yet: the graph commands Claude runs show up here', m.columns)] })]
  }

  const lines: RenderElement[] = []
  const recent = m.feed.slice(-Math.max(1, rows))
  // As wide as the longest op shown, so the deltas line up close to it, and
  // the deltas as wide as the widest (`~1n` adds to some).
  const opWidth = clamp(Math.max(...recent.map(op => widthOf(op.op))), 12, Math.max(12, m.columns - 30))
  const shown = recent.map(op => feedRow(op, opWidth))
  const deltaWidth = Math.max(...shown.map(row => widthOf(row.delta)))

  for (const [i, op] of recent.entries()) {
    const row = shown[i] ?? feedRow(op, opWidth)
    lines.push(
      Text({
        wrap: 'truncate-end',
        children: [
          Text({ dimColor: true, children: [row.time] }),
          Text({ color: 'claude', children: [' ▸ '] }),
          row.op,
          `  ${padEnd(row.delta, deltaWidth)}  `,
          Text({ dimColor: true, children: [row.ms] }),
          ' ',
          Text({ ...(op.isBackground ? { dimColor: true } : { color: op.ok ? 'success' : 'error' }), children: [row.mark] }),
        ],
      }),
    )
    if (isFull && !op.ok && op.error) {
      lines.push(Text({ color: 'error', dimColor: true, wrap: 'truncate-end', children: [fit(`         ${op.error}`, m.columns)] }))
    }
  }

  return isFull ? lines.slice(-Math.max(1, rows)) : lines
}

// ----------------------------------------------------------------- the queue

/** How many queued nodes one Queue page lists. */
export function queuePageSize(rows: number, conflicts: number): number {
  return Math.max(3, rows - 6 - (conflicts > 0 ? Math.min(conflicts, 5) + 1 : 0))
}

function queueTabOf(el: Table, m: PaneModel): RenderElement[] {
  const { Box, Button, Text } = el
  const queued = queueOf(m.graph, m.a)
  const conflicts = conflictsOf(m.graph, m.a)
  const size = queuePageSize(m.rows, conflicts.length)
  const pages = Math.max(1, Math.ceil(queued.length / size))
  const page = clamp(m.queuePage, 0, pages - 1)
  const lines: RenderElement[] = []

  if (m.notice !== null) {
    lines.push(Text({ color: 'success', wrap: 'truncate-end', children: [fit(clean(m.notice), m.columns)] }))
  }
  if (conflicts.length > 0) {
    lines.push(Text({ color: 'warning', wrap: 'truncate-end', children: [fit(`${plural(conflicts.length, 'open conflict')}: settle these before accepting what they name`, m.columns)] }))
    for (const id of conflicts.slice(0, 5)) {
      lines.push(Text({ wrap: 'truncate-end', children: [fit(clean(`  ! ${nameOf(m.graph, id)}  ${id}`), m.columns)] }))
    }
  }
  if (queued.length === 0) {
    lines.push(Text({ dimColor: true, children: [`no node is ${m.a.queueStatus.join(' or ') || 'queued'}`] }))

    return lines
  }

  lines.push(Text({ dimColor: true, wrap: 'truncate-end', children: [fit(`${queued.length} ${m.a.queueStatus.join('/')} · export writes one patch file each (status: ${m.a.acceptStatus})`, m.columns)] }))
  for (const id of queued.slice(page * size, page * size + size)) {
    const node = m.graph.nodes.get(id)
    lines.push(
      Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          Button({ key: `x:${id}`, label: 'export', onPress: () => m.act.exportPatch(id) }),
          Text({ wrap: 'truncate-end', children: [Text({ dimColor: true, children: [`${node?.label ?? '?'} · `] }), fit(node?.name ?? clean(id), Math.max(8, m.columns - 24))] }),
        ],
      }),
    )
  }
  lines.push(
    Box({
      flexDirection: 'row',
      columnGap: 2,
      children: [
        Button({ key: 'prev', label: 'prev', hotkey: 'p', plain: true, dimColor: page === 0, onPress: () => m.act.page(Math.max(0, page - 1)) }),
        Button({ key: 'next', label: 'next', hotkey: 'n', plain: true, dimColor: page >= pages - 1, onPress: () => m.act.page(Math.min(pages - 1, page + 1)) }),
        Text({ dimColor: true, children: [`page ${page + 1}/${pages}`] }),
      ],
    }),
  )

  return lines
}

// ------------------------------------------------------------------ the band

/** The band's one line: `◉ omnigraph · dev.omni · main · 8 ops · +3n +2e · 0 × · last mutate create_issue ✓ 652ms`. */
export function bandText(info: OmniInfo | null, totals: Totals, last: OmniOp | undefined): string {
  const parts = [
    'omnigraph',
    info?.name,
    info?.branch,
    info?.isPresent ? `${info.nodes}n ${info.edges}e` : undefined,
    totalsLine(totals),
    last ? `last ${last.op} ${last.isBackground ? '… bg' : `${last.ok ? '✓' : '✗'} ${msOf(last.ms)}`}` : undefined,
  ]

  return parts.filter((part): part is string => !!part).join(' · ')
}

files.hooks/graph-view.ts:
// The graph region of the pane: a Client surface module. It runs on the
// drawing thread with no `$`: it lays the props out (canvas.ts), draws the
// rows, and posts what the person did (an arrow key, a click, Enter) to the
// hooks module, whose ui.message hook moves the selection and answers with the
// next props.
import type { ClientModule, RenderElement } from 'claude-code'

import { hitTest, layoutEgo, stepFrom } from './canvas'
import type { EgoProps, Run, Step } from './canvas'

const STEPS: readonly string[] = ['up', 'down', 'left', 'right']
const TAB_KEYS: readonly string[] = ['1', '2', '3', '4']

const GraphView: ClientModule<EgoProps> = (props, surface) => {
  const { Box, Text } = surface.elements
  // 0 before the first layout: draw for the size the hooks module asked for.
  const columns = surface.columns > 0 ? surface.columns : props.columns
  const rows = surface.rows > 0 ? surface.rows : props.rows
  const layout = layoutEgo(props, columns, rows)

  surface.onKey(event => {
    if (STEPS.includes(event.key)) {
      const next = stepFrom(layout, props.selected, event.key as Step)
      if (next !== null && next !== props.selected) {
        surface.post({ kind: 'select', id: next })
      }
    } else if (event.key === 'return' || event.key === 'enter') {
      surface.post({ kind: 'open', id: props.selected })
    } else if (event.key === 'backspace' || event.key === 'h') {
      surface.post({ kind: 'back' })
    } else if (event.key === 'f') {
      surface.post({ kind: 'follow' })
    } else if (TAB_KEYS.includes(event.key)) {
      // The client holds the keys after a click: the pane's tab digits still switch tabs.
      surface.post({ kind: 'tab', tab: event.key })
    }
  })

  surface.onPointer(event => {
    if (event.type !== 'down') {
      return
    }
    const spot = hitTest(layout, event.x, event.y)
    if (spot === null) {
      return
    }
    if (spot.isMore) {
      surface.post({ kind: 'browse', id: props.center })
    } else {
      surface.post({ kind: spot.id === props.selected ? 'open' : 'select', id: spot.id })
    }
  })

  const runOf = (run: Run): RenderElement | string =>
    run.style === null
      ? run.text
      : Text({
          ...(run.style.color !== null && { color: run.style.color }),
          ...(run.style.bold && { bold: true }),
          ...(run.style.dim && { dimColor: true }),
          ...(run.style.inverse && { inverse: true }),
          ...(run.style.italic && { italic: true }),
          children: [run.text],
        })

  return Box({
    flexDirection: 'column',
    children: layout.rows.map(row => Text({ wrap: 'truncate-end', children: row.map(runOf) })),
  })
}

export default GraphView

files.hooks/canvas.ts:
// The node-link drawing: one node's neighbourhood laid out on a character grid
// (the node in the middle, its neighbours on two arcs, grouped by edge type),
// and the arrow-key and pointer rules that move the selection over it. Plain
// data in, plain data out: graph-view.ts draws it, the tests read it. Widths
// are terminal cells: a CJK character or an emoji takes two.
import { charWidth, cut, widthOf } from './text'

/** Colours for node labels, by the label's place in the store's sorted label list. */
export const PALETTE = [
  '#5fafff',
  '#ffaf5f',
  '#87d787',
  '#d787d7',
  '#ffd75f',
  '#5fd7d7',
  '#ff8787',
  '#afaf5f',
  '#87afff',
  '#d7af87',
  '#af87ff',
  '#87d7af',
] as const

export function colorOf(index: number): string {
  return PALETTE[((index % PALETTE.length) + PALETTE.length) % PALETTE.length] ?? PALETTE[0]
}

/** One node drawn: the centre, a neighbour, or `+N more` for the rest of its group. */
export type EgoNode = {
  id: string
  name: string
  label: string
  color: string
  side: 'center' | 'left' | 'right'
  /** Index into EgoProps.groups; -1 for the centre. */
  group: number
  isSelected: boolean
  isTouched: boolean
  /** Above 0: this is the `+N more` stand-in, `id` the group's key. */
  more: number
}

/** The neighbours one edge type and direction leads to. */
export type EgoGroup = { type: string; dir: 'out' | 'in'; count: number; side: 'left' | 'right'; title: string }

/** What the graph client draws: plain data, the Client's props. */
export type EgoProps = {
  center: string
  selected: string
  nodes: EgoNode[]
  groups: EgoGroup[]
  legend: { label: string; color: string }[]
  /** The size the hooks module laid it out for, until the client knows its own. */
  columns: number
  rows: number
  isFollowing: boolean
  /** Drawn instead of a graph: no store, no node. */
  empty: string | null
}

export type Style = { color: string | null; bold: boolean; dim: boolean; inverse: boolean; italic: boolean }
export type Run = { text: string; style: Style | null }

/** Where a node landed: its glyph and the cells of its label, for hits and arrow keys. */
export type Spot = { id: string; x: number; y: number; x0: number; x1: number; isMore: boolean }

export type Layout = { rows: Run[][]; spots: Spot[] }

/** One cell; the right half of a wide character is a tail with no text of its own. */
type Cell = { ch: string; style: Style | null; isLabel: boolean; isTail: boolean }

const blank = (): Cell => ({ ch: ' ', style: null, isLabel: false, isTail: false })

const PLAIN: Style = { color: null, bold: false, dim: false, inverse: false, italic: false }
const DOT: Style = { ...PLAIN, dim: true }
const EDGE_LABEL: Style = { ...PLAIN, dim: true, italic: true }

const clamp = (n: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, n))

class Grid {
  readonly cells: Cell[][]

  constructor(
    readonly columns: number,
    readonly rows: number,
  ) {
    this.cells = Array.from({ length: rows }, () => Array.from({ length: columns }, blank))
  }

  /** Puts one character at x, two cells when it is wide; the other half of a wide one it lands on goes blank. */
  put(x: number, y: number, ch: string, style: Style | null, isLabel: boolean, isWide = false): void {
    const row = this.cells[y]
    if (row === undefined || x < 0 || x + (isWide ? 1 : 0) >= this.columns) {
      return
    }
    this.free(row, x)
    row[x] = { ch, style, isLabel, isTail: false }
    if (isWide) {
      this.free(row, x + 1)
      row[x + 1] = { ch: '', style, isLabel, isTail: true }
    }
  }

  private free(row: Cell[], x: number): void {
    if (row[x]?.isTail && x > 0) {
      row[x - 1] = blank()
    } else if (row[x + 1]?.isTail) {
      row[x + 1] = blank()
    }
  }

  /** Writes `text` from x; false (and nothing written) when a label is in the way. */
  write(x: number, y: number, text: string, style: Style | null, isLabel: boolean, force = false): boolean {
    if (!force && !this.isFree(x, y, widthOf(text))) {
      return false
    }

    let at = x
    for (const ch of text) {
      const w = charWidth(ch.codePointAt(0) ?? 0)
      const before = this.cells[y]?.[at - 1]
      if (w === 0) {
        // A combining mark joins the character before it.
        if (at > x && before !== undefined) {
          before.ch += ch
        }
        continue
      }
      if (at + w > this.columns) {
        break
      }
      this.put(at, y, ch, style, isLabel, w === 2)
      at += w
    }

    return true
  }

  isFree(x: number, y: number, width: number): boolean {
    const row = this.cells[y]
    if (row === undefined || x < 0 || x + width > this.columns) {
      return false
    }

    return row.slice(x, x + width).every(cell => !cell.isLabel)
  }

  /** A dotted line between two cells, under whatever labels are there. */
  line(x0: number, y0: number, x1: number, y1: number): void {
    const dx = Math.abs(x1 - x0)
    const dy = -Math.abs(y1 - y0)
    const sx = x0 < x1 ? 1 : -1
    const sy = y0 < y1 ? 1 : -1
    let err = dx + dy
    let x = x0
    let y = y0

    for (let guard = 0; guard < 2000; guard++) {
      const cell = this.cells[y]?.[x]
      if (cell !== undefined && !cell.isLabel && cell.ch === ' ') {
        this.put(x, y, '·', DOT, false)
      }
      if (x === x1 && y === y1) {
        return
      }
      const e2 = 2 * err
      if (e2 >= dy) {
        err += dy
        x += sx
      }
      if (e2 <= dx) {
        err += dx
        y += sy
      }
    }
  }

  runs(): Run[][] {
    return this.cells.map(row => {
      const runs: Run[] = []

      for (const cell of row) {
        const last = runs[runs.length - 1]
        if (last !== undefined && sameStyle(last.style, cell.style)) {
          last.text += cell.ch
        } else {
          runs.push({ text: cell.ch, style: cell.style })
        }
      }

      return runs
    })
  }
}

function sameStyle(a: Style | null, b: Style | null): boolean {
  if (a === null || b === null) {
    return a === b
  }

  return a.color === b.color && a.bold === b.bold && a.dim === b.dim && a.inverse === b.inverse && a.italic === b.italic
}

/** The text a node's label shows. */
export function labelText(node: EgoNode, width: number): string {
  return node.more > 0 ? `+${node.more} more` : cut(node.name, width)
}

/** Lays the props out on a grid of `columns` x `rows` cells. */
export function layoutEgo(props: EgoProps, columns: number, rows: number): Layout {
  const width = clamp(Math.floor(columns), 1, 400)
  const height = clamp(Math.floor(rows), 1, 200)
  const grid = new Grid(width, height)
  const spots: Spot[] = []

  if (props.empty !== null || props.nodes.length === 0) {
    grid.write(0, 0, cut(props.empty ?? 'nothing to draw', width), { ...PLAIN, dim: true }, true, true)

    return { rows: grid.runs(), spots }
  }

  const hasLegend = height >= 6 && props.legend.length > 0
  const graphRows = hasLegend ? height - 1 : height
  // The hub's glyph sits in the middle with its name on the row under it, so
  // every edge starts at one point and the arcs get the width.
  const hasNameRow = graphRows >= 4
  const cy = Math.max(0, Math.floor((graphRows - (hasNameRow ? 2 : 1)) / 2))
  const cx = Math.floor(width / 2)
  const nameWidth = clamp(Math.floor(width * 0.3), 6, 26)
  const center = props.nodes.find(node => node.side === 'center') ?? props.nodes[0]
  if (center === undefined) {
    return { rows: grid.runs(), spots }
  }
  const centerName = cut(center.name, clamp(width - 2, 4, nameWidth + 6))
  const centerLength = widthOf(centerName)
  const nameY = hasNameRow ? cy + 1 : cy
  const nameX0 = hasNameRow ? clamp(cx - Math.floor(centerLength / 2), 0, Math.max(0, width - centerLength)) : cx + 2
  const taken: { y: number; x0: number; x1: number }[] = [
    { y: cy, x0: cx - 1, x1: cx + 1 },
    { y: nameY, x0: nameX0 - 1, x1: nameX0 + centerLength },
  ]
  const isOpen = (y: number, x0: number, x1: number) => taken.every(span => span.y !== y || x1 < span.x0 || x0 > span.x1)

  const placed: { node: EgoNode; x: number; y: number; text: string; x0: number }[] = []

  for (const side of ['left', 'right'] as const) {
    const nodes = props.nodes.filter(node => node.side === side)
    const n = nodes.length

    nodes.forEach((node, i) => {
      const text = labelText(node, nameWidth)
      const length = widthOf(text)
      // Where the glyph goes on row y: further out towards the middle rows, an arc.
      const xAt = (y: number) => {
        const dy = (y - cy) / Math.max(1, graphRows / 2)
        const arc = 0.25 + 0.75 * Math.sqrt(Math.max(0, 1 - dy * dy))
        if (side === 'right') {
          const outer = Math.max(cx + 3, width - 3 - length)
          return clamp(Math.round(cx + 3 + (outer - cx - 3) * arc), cx + 2, outer)
        }
        const outer = Math.min(cx - 3, length + 1)
        return clamp(Math.round(cx - 3 - (cx - 3 - outer) * arc), outer, cx - 2)
      }
      const spanAt = (y: number) => {
        const x = xAt(y)
        return side === 'right' ? { x, x0: x + 2, lo: x, hi: x + 1 + length } : { x, x0: x - 1 - length, lo: x - 1 - length, hi: x }
      }
      const ideal = n === 1 ? cy : clamp(Math.round(((i + 0.5) * graphRows) / n - 0.5), 0, graphRows - 1)

      // The nearest row to the ideal one where the glyph and the label fit.
      for (let d = 0; d < graphRows * 2; d++) {
        const y = ideal + (d % 2 === 0 ? d / 2 : -(d + 1) / 2)
        if (y < 0 || y >= graphRows) {
          continue
        }
        const span = spanAt(y)
        if (isOpen(y, span.lo - 1, span.hi + 1)) {
          taken.push({ y, x0: span.lo, x1: span.hi })
          placed.push({ node, x: span.x, y, text, x0: span.x0 })
          return
        }
      }
    })
  }

  // Edges first, from the hub's glyph to each node's; the labels then write over them.
  for (const spot of placed) {
    const isRight = spot.node.side === 'right'
    grid.line(isRight ? cx + 1 : cx - 1, cy, isRight ? spot.x - 1 : spot.x + 1, spot.y)
  }

  grid.put(cx, cy, '◉', { ...PLAIN, bold: true, color: center.color }, true)
  grid.write(nameX0, nameY, centerName, { ...PLAIN, bold: true, inverse: center.isSelected }, true, true)
  spots.push({ id: center.id, x: cx, y: cy, x0: cx - 1, x1: cx + 1, isMore: false })
  spots.push({ id: center.id, x: cx, y: nameY, x0: nameX0, x1: nameX0 + centerLength - 1, isMore: false })

  for (const spot of placed) {
    const { node } = spot
    const glyph = node.more > 0 ? '…' : node.isTouched ? '◆' : '●'
    const nameStyle: Style = { ...PLAIN, dim: node.more > 0, bold: node.isTouched, inverse: node.isSelected }
    const glyphStyle: Style = { ...PLAIN, color: node.color, bold: node.isTouched }
    const length = widthOf(spot.text)

    grid.put(spot.x, spot.y, glyph, glyphStyle, true)
    grid.write(spot.x0, spot.y, spot.text, nameStyle, true, true)
    spots.push({ id: node.id, x: spot.x, y: spot.y, x0: Math.min(spot.x, spot.x0), x1: Math.max(spot.x, spot.x0 + length - 1), isMore: node.more > 0 })
  }

  // One label per group, near the middle of its middle edge.
  props.groups.forEach((group, index) => {
    const members = placed.filter(spot => spot.node.group === index).sort((a, b) => a.y - b.y)
    const middle = members[Math.floor((members.length - 1) / 2)]
    if (middle === undefined) {
      return
    }
    const text = cut(group.title, Math.max(4, Math.floor(width / 3)))
    const length = widthOf(text)
    const midX = Math.round((cx + middle.x) / 2)
    const midY = Math.round((cy + middle.y) / 2)
    const x = clamp(midX - Math.floor(length / 2), 0, Math.max(0, width - length))

    // Off the hub's two rows, with a cell of air on each side.
    for (const y of [midY, midY - 1, midY + 1, midY - 2, midY + 2]) {
      const lo = Math.max(0, x - 1)
      const room = Math.min(width, x + length + 1) - lo
      if (y >= 0 && y < graphRows && y !== cy && y !== nameY && grid.isFree(lo, y, room) && grid.write(x, y, text, EDGE_LABEL, true)) {
        break
      }
    }
  })

  if (hasLegend) {
    let x = 0
    for (const entry of props.legend) {
      const text = `● ${entry.label}`
      const length = widthOf(text)
      if (x + length > width) {
        break
      }
      grid.put(x, height - 1, '●', { ...PLAIN, color: entry.color }, true)
      grid.write(x + 1, height - 1, ` ${entry.label}`, { ...PLAIN, dim: true }, true, true)
      x += length + 2
    }
  }

  return { rows: grid.runs(), spots }
}

export type Step = 'up' | 'down' | 'left' | 'right'

/**
 * The node an arrow key moves the selection to: the nearest one in a cone that
 * way (a row counts as two columns, as a cell is twice as tall as wide), else
 * the nearest one that way at all; null when there is none.
 */
export function stepFrom(layout: Layout, from: string, step: Step): string | null {
  const here = layout.spots.find(spot => spot.id === from) ?? layout.spots[0]

  if (here === undefined) {
    return null
  }

  const [ux, uy] = step === 'up' ? [0, -1] : step === 'down' ? [0, 1] : step === 'left' ? [-1, 0] : [1, 0]
  let best: { id: string; score: number } | null = null

  for (const spot of layout.spots) {
    if (spot.id === here.id || spot.isMore) {
      continue
    }
    const dx = spot.x - here.x
    const dy = (spot.y - here.y) * 2
    const along = dx * ux + dy * uy
    const across = Math.abs(dx * uy) + Math.abs(dy * ux)
    if (along <= 0) {
      continue
    }
    const score = Math.hypot(dx, dy) + (across > along ? 1000 : 0)
    if (best === null || score < best.score) {
      best = { id: spot.id, score }
    }
  }

  return best?.id ?? null
}

/** The node (or `+N more`) under a cell, or null. */
export function hitTest(layout: Layout, x: number, y: number): Spot | null {
  return layout.spots.find(s => s.y === y && x >= s.x0 - 1 && x <= s.x1 + 1) ?? null
}

/** A drawing's text, row by row: what a test or a log reads. */
export function textOf(layout: Layout): string[] {
  return layout.rows.map(row => row.map(run => run.text).join('').replace(/\s+$/, ''))
}

